"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, Plus, X, Clock, Trash2 } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem, deleteCalendarItem } from "@/app/actions/calendar-actions"; 
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");
  const [startTime, setStartTime] = useState("09:00");
  const [endTime, setEndTime] = useState("10:00");

  // Verileri eşleme (Timezone hatasını önlemek için manuel format)
  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      if (item.startDatetime) {
        const d = new Date(item.startDatetime);
        const dateKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    return map;
  }, [initialTasks]);

  const openAddModal = (date: Date) => {
    setEditingId(null);
    setSelectedDate(date);
    setTitle("");
    setType("agenda");
    setStartTime("09:00");
    setEndTime("10:00");
    setIsModalOpen(true);
  };

  const openEditModal = (e: React.MouseEvent, task: any) => {
    e.stopPropagation();
    setEditingId(task.id);
    setSelectedDate(new Date(task.startDatetime));
    setTitle(task.title);
    setType(task.description || "agenda");
    setStartTime(format(new Date(task.startDatetime), "HH:mm"));
    setEndTime(format(new Date(task.endDatetime), "HH:mm"));
    setIsModalOpen(true);
  };

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);
    try {
      const res = await createCalendarItem({
        id: editingId,
        titel: title,
        documentType: type,
        datum: format(selectedDate, "yyyy-MM-dd"),
        startTime,
        endTime
      });
      if (res.success) {
        setIsModalOpen(false);
        router.refresh();
        window.location.reload();
      }
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!editingId) return;
    setLoading(true);
    try {
      const res = await deleteCalendarItem(editingId);
      if (res.success) {
        setIsModalOpen(false);
        router.refresh();
        window.location.reload();
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-10 relative">
      {/* HEADER */}
      <div className="flex justify-between items-center mb-12 border-b border-white/5 pb-10">
        <div>
          <h1 className="text-6xl font-black text-white italic tracking-tighter uppercase leading-none drop-shadow-2xl text-white">Temporal Grid</h1>
          <p className="text-fuchsia-500 text-[10px] font-bold tracking-[0.7em] uppercase mt-3">Status: Actief</p>
        </div>
        <div className="flex items-center gap-6 bg-[#0a0e17]/80 border border-white/10 p-3 rounded-2xl backdrop-blur-xl text-white">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronLeft size={28} /></button>
          <span className="text-xl font-black w-56 text-center uppercase tracking-[0.2em] italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronRight size={28} /></button>
        </div>
      </div>

      {/* TAKVİM GRID */}
      <div className="bg-[#0a0e17]/90 border border-white/10 rounded-[40px] overflow-hidden shadow-2xl backdrop-blur-3xl text-white">
        <div className="grid grid-cols-7 bg-white/5 py-6 border-b border-white/10 text-center font-black text-teal-500/40 text-[11px] uppercase tracking-[0.5em]">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });
            while (day <= endDate) {
              const dObj = day;
              const dateKey = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(dObj.getDate()).padStart(2, '0')}`;
              const dayTasks = taskMap[dateKey] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              days.push(
                <div key={day.toString()} onClick={() => openAddModal(dObj)} className={`min-h-[170px] border border-white/5 p-5 transition-all cursor-pointer hover:bg-fuchsia-500/[0.03] relative group ${!isCurrentMonth ? "opacity-5" : ""}`}>
                  <span className="text-sm font-mono mb-3 block text-teal-500/20">{format(day, "d")}</span>
                  <div className="space-y-2">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} onClick={(e) => openEditModal(e, t)} className={`text-[10px] px-3 py-2 rounded-xl border font-bold uppercase tracking-tighter transition-transform hover:scale-105 ${t.description === 'agenda' ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'}`}>
                        <div className="flex justify-between items-center"><span className="truncate">{t.title}</span><span className="text-[8px] opacity-60 ml-1">{format(new Date(t.startDatetime), "HH:mm")}</span></div>
                      </div>
                    ))}
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#02040a]/95 backdrop-blur-xl px-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-12 rounded-[40px] w-full max-w-lg shadow-2xl relative text-white">
            <button onClick={() => setIsModalOpen(false)} className="absolute top-8 right-8 text-white/20 hover:text-white cursor-pointer"><X size={32} /></button>
            <div className="mb-10"><h3 className="text-fuchsia-500 font-black uppercase text-[11px] tracking-[0.6em] mb-4">{editingId ? "Aanpassen" : "Toevoegen"}</h3><p className="text-4xl font-black italic tracking-tighter uppercase leading-none">{selectedDate && format(selectedDate, "dd MMMM yyyy", { locale: nl })}</p></div>
            <div className="space-y-8">
              <input value={title} onChange={(e) => setTitle(e.target.value)} className="w-full bg-[#070B24] border border-white/10 p-6 text-white font-bold focus:border-fuchsia-500 outline-none rounded-2xl text-lg" placeholder="Titel..."/>
              <div className="bg-[#070B24] border border-white/10 rounded-2xl divide-y divide-white/5 overflow-hidden">
                <div className="flex justify-between items-center p-5"><span className="text-teal-500/40 text-[11px] font-black uppercase tracking-widest flex items-center gap-2"><Clock size={14}/> Start</span><input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="bg-[#0E153A] text-white p-2 rounded-lg font-mono outline-none"/></div>
                <div className="flex justify-between items-center p-5"><span className="text-teal-500/40 text-[11px] font-black uppercase tracking-widest flex items-center gap-2"><Clock size={14}/> Eind</span><input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="bg-[#0E153A] text-white p-2 rounded-lg font-mono outline-none"/></div>
              </div>
              <div className="flex gap-4">
                {editingId && (
                  <button onClick={handleDelete} className="flex-1 bg-red-600/20 text-red-500 font-black py-7 rounded-[24px] uppercase text-xs tracking-widest hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-2">
                    <Trash2 size={18} />
                  </button>
                )}
                <button onClick={handleSave} disabled={loading || !title} className="flex-[3] bg-white text-[#0E153A] font-black py-7 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-sm tracking-[0.5em] rounded-[24px] disabled:opacity-10">
                  {loading ? "Wachten..." : (editingId ? "Bijwerken" : "Bevestigen")}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}